<script setup>
import { reactive,ref,onMounted,computed } from 'vue'
import TouchKeyboard from './TouchKeyboard.vue'
import {api} from './api'
const language=ref(localStorage.getItem('sammoy-ui-language') || 'ru')
const tr=(ru,uz,en)=>({ru,uz,en}[language.value]||ru)
const theme=ref(localStorage.getItem('sammoy-ui-theme')==='dark'?'dark':'light')
function toggleTheme(){theme.value=theme.value==='light'?'dark':'light';document.documentElement.dataset.theme=theme.value;localStorage.setItem('sammoy-ui-theme',theme.value)}
document.documentElement.dataset.theme=theme.value
const status=ref(null),error=ref(''),notice=ref(''),busy=ref(false),tab=ref('online'),confirm=ref(false),wash=ref(null)
const form=reactive({gateway_url:'',activation_code:'',site_code:'',post_no:1,purpose:'activate',click_enabled:false})
const safeToInstall=computed(()=>wash.value && !wash.value.activeMode && Number(wash.value.creditSum)===0)
async function load(){status.value=await api('/api/commissioning/status');wash.value=(await api('/api/wash/state')).state;if(!form.gateway_url)form.gateway_url=status.value.site.gateway_url.includes('example.com')?'':status.value.site.gateway_url;form.site_code ||= status.value.site.site_code;form.post_no=status.value.site.post_no || 1}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function ensureIdle(){wash.value=(await api('/api/wash/state')).state;if(!safeToInstall.value)throw Error(tr('Завершите сеанс мойки перед активацией поста.','Postni faollashtirishdan oldin yuvish seansini yakunlang.','Finish the wash session before station activation.'))}
async function claim(){await ensureIdle();status.value=await api('/api/commissioning/claim',{method:'POST',body:JSON.stringify({gateway_url:form.gateway_url,activation_code:form.activation_code,click_enabled:form.click_enabled})});form.activation_code='';notice.value=tr('Пост активирован. Проверьте данные и завершите установку.','Post faollashtirildi. Ma’lumotlarni tekshiring va sozlashni yakunlang.','Station activated. Check the details and finish setup.')}
async function download(){const {activation_code,...payload}=form;const data=await api('/api/commissioning/offline-request',{method:'POST',body:JSON.stringify(payload)});const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sammoy-post-'+form.post_no+'.request.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importResponse(event){const file=event.target.files?.[0];if(!file)return;await run(async()=>{await ensureIdle();const data=new FormData();data.append('file',file);const r=await fetch('/api/commissioning/offline-response',{method:'POST',body:data,signal:AbortSignal.timeout(60000)});const body=await r.json();if(!r.ok)throw Error(body.detail || 'Import failed');status.value=body;notice.value=tr('Ответ импортирован','Javob import qilindi','Response imported')});event.target.value=''}
async function complete(){await ensureIdle();status.value=await api('/api/commissioning/complete',{method:'POST',body:JSON.stringify({confirmation:'READY'})});confirm.value=false;notice.value=tr('Установка завершена. Войдите в Owner → Telegram на посте 1, подключите бота и найдите остальные посты.','Sozlash yakunlandi. 1-postda Owner → Telegram orqali botni ulang va boshqa postlarni toping.','Setup complete. Open Owner → Telegram on station 1 to connect the bot and discover other stations.')}
onMounted(()=>run(load))
</script>
<template><main class="shell"><header class="topbar"><div class="brand"><strong>Labrixwash</strong><span>{{ tr('Установка поста','Postni sozlash','Station setup') }}</span></div><div class="top-actions"><button class="quiet" @click="toggleTheme">{{ theme==='light'?'◐ Dark':'☀ Light' }}</button><div class="language"><button v-for="lang in ['ru','uz','en']" :class="{active:language===lang}" @click="language=lang">{{ lang.toUpperCase() }}</button></div><a class="quiet install-link" href="/login">{{ tr('Вход','Kirish','Sign in') }}</a></div></header>
<section class="owner-page"><div class="heading"><h1>{{ tr('Настройка новой мойки','Yangi yuvishni sozlash','New wash setup') }}</h1><p>{{ tr('Установите каждый пост отдельно. Код мойки и общий ключ выдаёт сервер активации; номера постов должны различаться.','Har bir postni alohida sozlang. Yuvish kodi va umumiy kalit faollashtirish serveridan olinadi; post raqamlari turlicha bo‘lishi kerak.','Set up each station separately. The activation server supplies the site code and shared key; station numbers must be unique.') }}</p></div>
<div v-if="error" class="message error" role="alert">{{ error }}</div><div v-if="notice" class="message success" role="status">{{ notice }}</div><p v-if="busy" role="status">{{ tr('Загрузка…','Yuklanmoqda…','Loading…') }}</p>
<template v-if="status"><div class="metrics"><section class="card metric"><p>{{ tr('Контроллер','Kontroller','Controller') }}</p><strong>{{ status.hardware.complete?'OK':'—' }}</strong></section><section class="card metric"><p>Modbus I/O</p><strong>{{ status.io_ready?'OK':'—' }}</strong></section><section class="card metric"><p>{{ tr('Код мойки','Yuvish kodi','Site code') }}</p><strong>{{ status.site.site_code || '—' }}</strong></section><section class="card metric"><p>{{ tr('Пост','Post','Station') }}</p><strong>{{ status.site.post_no }}</strong></section></div>
<template v-if="!status.commissioning.complete"><div v-if="!safeToInstall" class="message error">{{ tr('На посте есть незавершённый сеанс. Активация доступна после его завершения.','Postda yakunlanmagan seans bor. Faollashtirish u yakunlangach mumkin.','A wash session is still open. Activation is available after it is finished.') }}<button class="quiet" :disabled="busy" @click="run(load)">{{ tr('Обновить','Yangilash','Refresh') }}</button></div>
<div class="actions" style="margin-bottom:24px"><button class="quiet" @click="tab='online'">{{ tr('По коду активации','Faollashtirish kodi','Activation code') }}</button><button class="quiet" @click="tab='offline'">{{ tr('Через файл','Fayl orqali','Via file') }}</button></div>
<form v-if="tab==='online'" class="card content" @submit.prevent="run(claim)"><div class="fields"><label>{{ tr('Адрес сервера активации','Faollashtirish serveri manzili','Activation server address') }}<input v-model.trim="form.gateway_url" type="url" placeholder="https://…" required maxlength="300" /></label><label>{{ tr('Код активации поста','Postni faollashtirish kodi','Station activation code') }}<input v-model.trim="form.activation_code" minlength="8" maxlength="32" required autocomplete="off" /></label><label class="check"><input v-model="form.click_enabled" type="checkbox" />{{ tr('Включить Click','Clickni yoqish','Enable Click') }}</label><button class="primary" :disabled="busy || !safeToInstall || !status.hardware.complete || !status.io_ready">{{ tr('Активировать пост','Postni faollashtirish','Activate station') }}</button></div></form>
<form v-else class="card content" @submit.prevent="run(download)"><div class="fields"><label>{{ tr('Код мойки','Yuvish kodi','Site code') }}<input v-model.trim="form.site_code" maxlength="80" required /></label><label>{{ tr('Номер поста','Post raqami','Station number') }}<input v-model.number="form.post_no" type="number" min="1" max="1000" required /></label><label>{{ tr('Адрес сервера активации','Faollashtirish serveri manzili','Activation server address') }}<input v-model.trim="form.gateway_url" type="url" required maxlength="300" /></label><label>{{ tr('Назначение','Maqsad','Purpose') }}<select v-model="form.purpose"><option value="activate">{{ tr('Новый пост','Yangi post','New station') }}</option><option value="replace_microsd">{{ tr('Замена microSD','microSD almashtirish','Replace microSD') }}</option></select></label><div class="full"><p class="muted">{{ tr('Скачайте запрос, подтвердите его на сервере активации и загрузите подписанный файл ответа.','So‘rovni yuklab oling, faollashtirish serverida tasdiqlang va imzolangan javob faylini yuklang.','Download the request, approve it on the activation server, then upload the signed response.') }}</p><button class="quiet" :disabled="busy || !status.hardware.complete">{{ tr('Скачать запрос','So‘rovni yuklab olish','Download request') }}</button></div><label>{{ tr('Файл ответа','Javob fayli','Response file') }}<input type="file" accept="application/json,.json" :disabled="busy || !safeToInstall" @change="importResponse" /></label></div></form>
<div class="actions end"><button class="quiet" :disabled="busy" @click="run(load)">{{ tr('Обновить','Yangilash','Refresh') }}</button><button class="primary" :disabled="busy || !safeToInstall || !status.site.site_code || status.license.locked || !status.io_ready" @click="confirm=true">{{ tr('Завершить установку','Sozlashni yakunlash','Finish setup') }}</button></div></template><p v-else class="message success">{{ tr('Установка этого поста завершена.','Ushbu postni sozlash yakunlangan.','This station setup is complete.') }}</p></template></section>
<div v-if="confirm" class="confirm-backdrop"><section class="card confirm-dialog" role="alertdialog" aria-modal="true"><h2>{{ tr('Завершить установку поста','Post sozlamalarini yakunlash','Complete station setup') }} {{ status.site.post_no }}?</h2><p>{{ status.site.site_code }}</p><div class="actions"><button class="quiet" @click="confirm=false">{{ tr('Отмена','Bekor qilish','Cancel') }}</button><button class="primary" :disabled="busy" @click="run(complete)">{{ tr('Подтвердить','Tasdiqlash','Confirm') }}</button></div></section></div><TouchKeyboard :language="language" /></main></template>
